CREATE TABLE IF NOT EXISTS `motherland_district` (
  `id` bigint unsigned NOT NULL,
  `pid` bigint DEFAULT NULL COMMENT '父级地区id',
  `code` varchar(255) DEFAULT NULL COMMENT '区划编码',
  `name` varchar(255) DEFAULT NULL COMMENT '区划名称',
  `level` int DEFAULT NULL COMMENT '级别 1:省/自治区/直辖市 2:市级 3:县级 4:街道',
  `center` varchar(100) DEFAULT NULL COMMENT '经纬度',
  `city_code` varchar(100) DEFAULT NULL COMMENT '城市编码',
  `status` int DEFAULT NULL COMMENT '状态 0=弃用,1=使用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint unsigned DEFAULT NULL,
  `create_by` varchar(20) DEFAULT NULL,
  `update_by` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='国家区域表';

